INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 10, 'theory', 'Quiz: promises and async/await');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 10, 0, 'In what order will the lines be printed: setTimeout(log(''T''), 0); Promise.resolve().then(log(''P'')); log(''S'')?', '["T, P, S", "S, P, T", "S, T, P", "P, S, T"]', 1, 'First the synchronous code (S), then the microtasks, which are promise handlers (P), and only then the timers (T).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 10, 1, 'How does Promise.allSettled differ from Promise.all?', '["allSettled is faster", "allSettled starts promises one at a time", "allSettled always waits for all and reports each outcome, while all rejects on the first error", "There is no difference"]', 2, 'allSettled returns an array of objects { status, value | reason }, so one failure does not hide the results of the others.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 10, 2, 'Why does await inside items.forEach(async x => …) not wait for all the operations to finish?', '["forEach cannot wait: it calls the functions and returns at once, ignoring the promises they return", "Because await works only in for loops", "Because the array is empty", "Because of strict mode"]', 0, 'For sequential waiting use for…of with await, and for parallel waiting use Promise.all(items.map(…)).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 10, 3, 'What is the right way to "cancel" a fetch request?', '["Call promise.cancel()", "Assign the promise to null", "Use setTimeout", "Pass fetch a signal from an AbortController and call abort()"]', 3, 'A promise doesn''t cancel itself; fetch listens to the signal and rejects with AbortError, and your own operations must subscribe to the abort event.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 10, 4, 'What does an async function return if it executes return 42?', '["The number 42", "A promise fulfilled with the value 42", "undefined", "An Error object"]', 1, 'An async function always returns a promise: the value becomes the result, and an exception becomes the reason for rejection.');
